import{_ as a,o as e,c as o,a0 as r}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"方法正文收尾，结果写了一半","description":"今天写完了论文方法部分的正文，但补充材料里该放的内容还没整理；结果章节写到大半，智能体测试仍有些问题待调，明天接着看。","frontmatter":{"title":"方法正文收尾，结果写了一半","date":"2026-08-24T00:00:00.000Z","tags":["日记"],"description":"今天写完了论文方法部分的正文，但补充材料里该放的内容还没整理；结果章节写到大半，智能体测试仍有些问题待调，明天接着看。"},"headers":[],"relativePath":"posts/diary-20260824.md","filePath":"posts/diary-20260824.md","lastUpdated":1787579519000}'),s={name:"posts/diary-20260824.md"};function n(p,t,i,d,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="方法正文收尾-结果写了一半" tabindex="-1">方法正文收尾，结果写了一半 <a class="header-anchor" href="#方法正文收尾-结果写了一半" aria-label="Permalink to &quot;方法正文收尾，结果写了一半&quot;">​</a></h1><p>今天在论文上推进了一块实打实的内容——<strong>方法（Methods）部分的正文写完了</strong>。</p><h2 id="方法正文搞定-但补充材料还空着" tabindex="-1">方法正文搞定，但补充材料还空着 <a class="header-anchor" href="#方法正文搞定-但补充材料还空着" aria-label="Permalink to &quot;方法正文搞定，但补充材料还空着&quot;">​</a></h2><p>方法这块正文总算落笔收尾，主线逻辑顺下来了。不过心里有数：很多细枝末节、参数表、额外实验，按规矩是得放进<strong>补充文件（Supplementary）<strong>里的，这些今天</strong>还没整理</strong>。</p><p>说白了正文只是&quot;主干&quot;， supplement 才是把论证撑结实的那部分。回头得专门腾一段时间，把那些散布在各处的细节归拢进去，不然审稿人一抠就露怯。</p><h2 id="结果写了一半" tabindex="-1">结果写了一半 <a class="header-anchor" href="#结果写了一半" aria-label="Permalink to &quot;结果写了一半&quot;">​</a></h2><p><strong>结果（Results）章节写到了差不多一半</strong>。这部分的难处不在于&quot;写&quot;，而在于得跟图、跟表对齐——哪张图对应哪段结论、数据能不能撑住说法，得反复核对。现在进度过半，剩下那半争取尽快收掉。</p><h2 id="智能体测试还有坑" tabindex="-1">智能体测试还有坑 <a class="header-anchor" href="#智能体测试还有坑" aria-label="Permalink to &quot;智能体测试还有坑&quot;">​</a></h2><p>折腾智能体的时候，测试跑起来会<strong>出些问题</strong>：有些边界情况没兜住，有些流程跑到一半就卡住。眼下能定位到&quot;需要调整&quot;，但具体怎么改顺，脑子有点转不动了。</p><p>这种事硬扛效率不高，先记一笔：<strong>明天再看看</strong>，换个状态再来调，估计比今晚死磕来得快。</p><p>今天方法收尾、结果过半，算是稳步往前挪了一步。剩下的 supplement 和智能体调优，明天见。</p>',11)])])}const _=a(s,[["render",n]]);export{c as __pageData,_ as default};
